examples.code:
function greet(name, greeting = 'Привет') {
  return greeting + ', ' + name + '!';
}

function sum(...numbers) {   // numbers — массив всех переданных аргументов
  let total = 0;
  for (const n of numbers) total += n;
  return total;
}

document.body.append(
  greet('Ия') + ' | ' + greet('Ия', 'Здравствуй') + ' | ' + sum(1, 2, 3) + ' | ' + sum()
);

const order = {
  cafe: 'Кофеин',
  total: 430,
  describe() {
    // у стрелки нет своего this — она берёт его из describe()
    const makeLine = () => this.cafe + ': ' + this.total + ' руб.';
    return makeLine();
  },
};

document.body.append(order.describe());

